#pragma once
#include "session_state.h"
static std::wstring sessionStatePath(){auto p=displayPreferencesPath();return p.substr(0,p.find_last_of(L"\\/"))+L"\\last-view-v1.bin";}
static sessionState::State captureSessionState(){
    sessionState::State s;s.view=captureExperienceView();s.selected=gCol>=0;s.basemap=gMap==gMapNasa&&gMapNasa?2:(gMap==gMapHighRes&&gMapHighRes?1:0);s.year=gHistoryYear;s.workspace=(int)gWorkspace;s.infoTab=gInfoTab;s.regionPage=gRegionPage;s.layers=(gShowHistory?1:0)|(gShowWorld2026?2:0)|(gShowPopulation?4:0)|(gShowLandCover?8:0);
    if(gRouteIndex>=0&&(size_t)gRouteIndex<routes::catalog().size()){const auto& route=routes::catalog()[gRouteIndex];std::string id=route.id;s.routeId.assign(id.begin(),id.end());if(gRouteDistance.length()>0)s.routeFraction=bounded(gRouteDistance.at(gRouteProgress)/gRouteDistance.length(),0.,1.);}return s;
}
static void saveLastView(){if(!gSessionReady||!gRestoreLastView)return;if(!gSessionValidated){sessionState::State previous;auto path=sessionStatePath();gSessionUnreadable=GetFileAttributesW(path.c_str())!=INVALID_FILE_ATTRIBUTES&&!sessionState::read(path,previous);gSessionValidated=true;}if(!gSessionUnreadable)sessionState::write(sessionStatePath(),captureSessionState());}
static void restoreLastView(HWND window){
    if(!gRestoreLastView)return;gSessionValidated=true;sessionState::State s;auto path=sessionStatePath();if(!sessionState::read(path,s)){gSessionUnreadable=GetFileAttributesW(path.c_str())!=INVALID_FILE_ATTRIBUTES;if(gSessionUnreadable)gNotice=gEnglish?L"The previous view could not be read. Choose Start a new exploration in Display to create a new view record.":L"上次视图无法读取。可在“显示”中选择“开始新探索”，原记录会保留备份。";return;}
    if(s.basemap)SendMessageW(window,WM_COMMAND,MAKEWPARAM(1120+s.basemap,BN_CLICKED),0);
    int year=-1;for(int i=0;i<HISTORY_YEAR_COUNT;++i)if(HISTORY_YEARS[i]==s.year){year=i;break;}if(year>=0){SendMessageW(gHistoryYearCombo,CB_SETCURSEL,year,0);SendMessageW(window,WM_COMMAND,MAKEWPARAM(1010,CBN_SELCHANGE),(LPARAM)gHistoryYearCombo);}
    gWorkspace=(ExplorerWorkspace)s.workspace;gRoutePanelOpen=gWorkspace==ExplorerWorkspace::Routes;gInfoTab=s.infoTab;gRegionPage=s.regionPage;gScrollOffset=0;gInfoWheelRemainder=0;
    gGridLevel=s.view.grid;SendMessageW(gGridLevelCombo,CB_SETCURSEL,gGridLevel,0);gMapZoom=bounded(s.view.zoom,1.,mapZoomLimit());gMapCenterX=s.view.cx;gMapCenterY=s.view.cy;
    gSelectedLatitude=s.view.latitude;gSelectedLongitude=s.view.longitude;gSelectedCoordinateExact=s.view.exact;gSelectedCoordinateFromInput=s.view.input;gSelectedCoordinateIsFineGridCenter=s.view.fine;gSelectedPlaceTitle=s.view.name;gSelectedPlaceOrigin=s.view.origin;
    gRow=s.selected?std::max(0,std::min(GRID_ROWS-1,(int)std::floor((90-s.view.latitude)/GRID_CELL_DEGREES))):-1;gCol=s.selected?std::max(0,std::min(GRID_COLUMNS-1,(int)std::floor((s.view.longitude+180)/(360./GRID_COLUMNS)))):-1;
    gShowHistory=(s.layers&1)&&gHistoryLoaded;gShowWorld2026=(s.layers&2)&&gWorld2026Loaded;gShowPopulation=(s.layers&4)&&gPopulationLoaded;gShowLandCover=(s.layers&8)&&gLandCoverLoaded;
    for(auto item:std::initializer_list<std::pair<HWND,bool>>{{gHistoryToggleButton,gShowHistory},{gWorld2026ToggleButton,gShowWorld2026},{gPopulationToggleButton,gShowPopulation},{gLandCoverToggleButton,gShowLandCover}})if(item.first)SendMessageW(item.first,BM_SETCHECK,item.second?BST_CHECKED:BST_UNCHECKED,0);
    gRouteIndex=-1;for(size_t i=0;i<routes::catalog().size();++i){std::string id=routes::catalog()[i].id;if(std::wstring(id.begin(),id.end())==s.routeId){gRouteIndex=(int)i;break;}}
    gRoutePlaying=false;gHistoryPlaying=false;gHistoryPaused=false;if(gRouteIndex>=0){gRouteDistance=routes::DistanceProfile(routes::pointsFor(routes::catalog()[gRouteIndex]));gRouteDistanceIndex=gRouteIndex;gRouteProgress=gRouteDistance.progress(gRouteDistance.length()*s.routeFraction);updateRouteRaster();}
    refreshSelectedReferenceLanguage();layoutControls(window);clampMapView();updateRouteControls();updateHistoryPlaybackButton();syncExperienceControls();gMapSceneCacheValid=false;gNotice=gEnglish?L"Previous view restored · choose Start a new exploration in Display to begin again.":L"已恢复上次视图 · 可在“显示”中选择“开始新探索”。";
}
static void startFreshExploration(HWND window){
    commitHistorySeek(window);KillTimer(window,HISTORY_PLAYBACK_TIMER);KillTimer(window,ROUTE_PLAYBACK_TIMER);KillTimer(window,NAVIGATION_CAPTURE_TIMER);finishHistoryTransition(window);gHistoryPlaying=false;gHistoryPaused=false;gHistoryEventRelayMode=false;gRoutePlaying=false;gRouteIndex=-1;gRouteProgress=0;delete gRouteRaster;gRouteRaster=nullptr;
    SendMessageW(gHistoryYearCombo,CB_SETCURSEL,0,0);SendMessageW(window,WM_COMMAND,MAKEWPARAM(1010,CBN_SELCHANGE),(LPARAM)gHistoryYearCombo);gShowHistory=gShowWorld2026=gShowPopulation=gShowLandCover=false;for(HWND c:{gHistoryToggleButton,gWorld2026ToggleButton,gPopulationToggleButton,gLandCoverToggleButton})if(c)SendMessageW(c,BM_SETCHECK,BST_UNCHECKED,0);
    gWorkspace=ExplorerWorkspace::Browse;gRoutePanelOpen=false;gInfoTab=0;gRegionPage=0;gCol=gRow=-1;gSelectedLatitude=gSelectedLongitude=0;gSelectedCoordinateExact=gSelectedCoordinateFromInput=gSelectedCoordinateIsFineGridCenter=false;gSelectedPlaceTitle.clear();gSelectedPlaceOrigin.clear();gScrollOffset=0;gInfoWheelRemainder=0;SetWindowTextW(gSearchEdit,L"");gLastSearchQuery.clear();gSearchMatches.clear();gSearchMatchIndex=0;gSearchWasLegacy=false;resetMapView();gExperiencePanel=0;layoutControls(window);updateRouteControls();updateHistoryPlaybackButton();gViewHistory.reset(captureExperienceView());syncExperienceControls();
    if(gSessionUnreadable){auto path=sessionStatePath(),backup=path+L".unreadable."+std::to_wstring(GetTickCount64())+L".bak";if(MoveFileExW(path.c_str(),backup.c_str(),0)||GetFileAttributesW(path.c_str())==INVALID_FILE_ATTRIBUTES)gSessionUnreadable=false;}
    gSessionValidated=true;saveLastView();gNotice=gSessionUnreadable?(gEnglish?L"New exploration started; the old view record could not be backed up, so the new view was not saved.":L"已开始新探索；旧视图记录暂时无法备份，未保存新的视图。"):(gEnglish?L"A new exploration is ready":L"已开始新的探索");InvalidateRect(window,nullptr,FALSE);
}
